<?php
declare(strict_types=1);

/* Stable SmartToolz Admin entry point. Keep this file dependency-light. */
require_once __DIR__ . '/bootstrap.php';
$admin = requireAdmin();
$db = adminDb();

function h(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function countSafe(PDO $db, string $sql): int { try { return (int)$db->query($sql)->fetchColumn(); } catch (Throwable $e) { error_log($e->getMessage()); return 0; } }
function rowsSafe(PDO $db, string $sql): array { try { return $db->query($sql)->fetchAll(PDO::FETCH_ASSOC); } catch (Throwable $e) { error_log($e->getMessage()); return []; } }

$tab = (string)($_GET['tab'] ?? 'dashboard');
$tabs = ['dashboard','analytics','ads','settings','users'];
if (!in_array($tab, $tabs, true)) $tab = 'dashboard';

$live = countSafe($db, "SELECT COUNT(*) FROM analytics_live WHERE last_seen >= DATE_SUB(NOW(), INTERVAL 5 MINUTE)");
$todayViews = countSafe($db, "SELECT COUNT(*) FROM analytics_pageviews WHERE viewed_at >= CURDATE()");
$todayDownloads = countSafe($db, "SELECT COUNT(*) FROM download_tracking WHERE created_at >= CURDATE()");
$usersCount = countSafe($db, "SELECT COUNT(*) FROM creator_users");
$totalViews = countSafe($db, "SELECT COUNT(*) FROM analytics_pageviews");
$totalDownloads = countSafe($db, "SELECT COUNT(*) FROM download_tracking");
$totalToolUses = countSafe($db, "SELECT COUNT(*) FROM tool_usage");

$topPages = rowsSafe($db, "SELECT page_path label, COUNT(*) c FROM analytics_pageviews WHERE viewed_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY page_path ORDER BY c DESC LIMIT 10");
$topTools = rowsSafe($db, "SELECT tool_slug label, COUNT(*) c FROM tool_usage WHERE created_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY tool_slug ORDER BY c DESC LIMIT 10");
$countries = rowsSafe($db, "SELECT COALESCE(NULLIF(country,''),'Unknown') label, COUNT(*) c FROM analytics_pageviews WHERE viewed_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY country ORDER BY c DESC LIMIT 10");
$devices = rowsSafe($db, "SELECT COALESCE(NULLIF(device,''),'Other') label, COUNT(*) c FROM analytics_pageviews WHERE viewed_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY device ORDER BY c DESC LIMIT 8");
$browsers = rowsSafe($db, "SELECT COALESCE(NULLIF(browser,''),'Other') label, COUNT(*) c FROM analytics_pageviews WHERE viewed_at >= DATE_SUB(NOW(), INTERVAL 30 DAY) GROUP BY browser ORDER BY c DESC LIMIT 8");
$liveRows = rowsSafe($db, "SELECT visitor_id,page_path,country,city,device,browser,last_seen FROM analytics_live WHERE last_seen >= DATE_SUB(NOW(), INTERVAL 5 MINUTE) ORDER BY last_seen DESC LIMIT 30");
?>
